parameters.jsCode:
const incident =
  $('Normalize Incident Input').first().json;

const pipeline =
  $('Get Pipeline Evidence').first().json;

const duplicates =
  $('Get Duplicate Evidence')
    .all()
    .map(item => item.json);

const priceAnomalies =
  $('Get Price Anomaly Evidence')
    .all()
    .map(item => item.json);

const missingSource =
  $('Get Missing Source Evidence').first().json;

return [
  {
    json: {
      incident_date: incident.incident_date,
      run_id: incident.run_id,

      data_quality: incident.data_quality,

      analytics: incident.analytics,

      evidence: {
        pipeline: pipeline,
        duplicate_orders: duplicates,
        price_anomalies: priceAnomalies,
        missing_source: missingSource
      }
    }
  }
];

